def admit_source(source, owner_sources, provider_source=None):
    """Source-only whole FN/module inverse; not runtime or strict acceptance."""
    tree=ast.parse(source)
    if ast.dump(tree,include_attributes=False)!=EXPECTED_MODULE_AST:
        raise ValueError('complete admitted cooperative source module differs')
    constants={}
    for node in tree.body:
        if isinstance(node,ast.Assign) and len(node.targets)==1 and isinstance(node.targets[0],ast.Name) and node.targets[0].id in (
                'VIEW_SPECS','EXPECTED_SOURCE','EXPECTED_SYNCHRONOUS_SOURCE','EXPECTED_PROVIDER_SOURCE','MODULE_PATHS'):
            constants[node.targets[0].id]=ast.literal_eval(node.value)
    if set(owner_sources)!=set(constants['MODULE_PATHS']):
        raise ValueError('all explicit original cooperative source modules required')
    namespace=dict(ast=ast,copy=copy,VIEW_SPECS=constants['VIEW_SPECS'],EXPECTED_SOURCE=constants['EXPECTED_SOURCE'])
    definitions=[node for node in tree.body if isinstance(node,ast.FunctionDef) and node.name in ('_dump','_cooperative_module')]
    if len(definitions)!=2:raise ValueError('both whole-module inverse utilities required')
    exec(compile(ast.Module(body=definitions,type_ignores=[]),'<whole cooperative source inverse>','exec'),namespace)
    for group,text in owner_sources.items():
        original=ast.parse(text)
        expected=dict(constants['EXPECTED_SYNCHRONOUS_SOURCE'].get(group,{}))
        expected.update(constants['EXPECTED_SOURCE'].get(group,{}))
        nodes={node.name:node for node in original.body if isinstance(node,ast.FunctionDef)}
        for name,source_text in expected.items():
            if name not in nodes or ast.dump(nodes[name],include_attributes=False)!=ast.dump(ast.parse(source_text).body[0],include_attributes=False):
                raise ValueError('complete original cooperative owner differs: '+name)
        if group in constants['VIEW_SPECS']:
            compile(namespace['_cooperative_module'](group,original),'<whole cooperative source>','exec',dont_inherit=True)
    if 'EXPECTED_PROVIDER_SOURCE' in constants:
        if type(provider_source)is not str:raise ValueError('actual complete Battle provider source required')
        owners=[node for node in ast.parse(provider_source).body if isinstance(node,ast.ClassDef) and node.name=='BattleScenePrograms']
        if len(owners)!=1:raise ValueError('one complete actual Battle provider required')
        nodes={node.name:node for node in owners[0].body if isinstance(node,ast.FunctionDef)}
        for name,text in constants['EXPECTED_PROVIDER_SOURCE'].items():
            if name not in nodes or ast.dump(nodes[name],include_attributes=False)!=ast.dump(ast.parse(text).body[0],include_attributes=False):
                raise ValueError('actual complete Battle provider method differs: '+name)
    return dict(source_only=True,complete_module_inverse=True,formal_credit=0,
        game=False,fixture=False,normal_API=False,native=False,hash=False,strict_pending_unchanged=46004)
